-- ROLLBACK for 20261006220000_m820_3_hints.sql — restores the pre-block descriptions (inventory snapshot 20261006).
BEGIN;
UPDATE fields x SET description = 'Mehrfachauswahl der beauftragten Leistungsphasen (§1): LPH 0 Bedarfsplanung … LPH 9 Objektbetreuung (HOAI/AHO).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'applicable_lph';
UPDATE fields x SET description = 'Auftraggeber organisation' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'client_name';
UPDATE fields x SET description = 'Contract / Vertrags-Nr.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'contract_reference';
UPDATE fields x SET description = 'Auftragnehmer / planning engineering office' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'contractor_auftragnehmer';
UPDATE fields x SET description = 'Is the project scoped to also apply Teil 1 (Vorbereitung und Vergabeverfahren)?' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'part1_applicable';
UPDATE fields x SET description = 'Is the project scoped to also apply Teil 2 (Durchführung)?' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'part2_applicable';
UPDATE fields x SET description = 'Project geographic location' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'project_location';
UPDATE fields x SET description = 'Project title' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'project_name';
UPDATE fields x SET description = 'Internal project number / ID' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'project_number';
UPDATE fields x SET description = 'Gesamtsystem (overall system) / Einzelprojekt (single project) / Both. The regulation makes this distinction the elementary basis of the workflow.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'project_type';
UPDATE fields x SET description = 'Date the project was registered in this workbook' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'registration_date';
UPDATE fields x SET description = 'Project covers Abfall?' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'sector_abfall';
UPDATE fields x SET description = 'Project covers Abwasser?' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'sector_abwasser';
UPDATE fields x SET description = 'Project covers Wasserbau?' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'sector_wasserbau';
UPDATE fields x SET description = 'Project covers Wasserwirtschaft?' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'sector_wasserwirtschaft';
UPDATE fields x SET description = 'Plan 3: Mehrfachauswahl über die vier gedruckten Bereiche (L196) neben den vier Booleans sector_* (REQ-01 liest die Booleans weiter — Ablösung STAGED m820_3-J-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'sektoren';
UPDATE compliance_requirements x SET description = 'Project confirmed to be within the regulation''s Anwendungsbereich: planning work for facilities in Wasserwirtschaft, Wasserbau, Abwasser or Abfall, with AG/AN parties identified.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.code = 'REQ-01';
UPDATE fields x SET description = 'Project-specific Anforderungen und Aufgabenlisten developed from QE; documented in working documents (e.g. checklists).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'anw_hinweis_1_confirmed';
UPDATE fields x SET description = 'QE are Anhaltspunkte; Vervollständigung im Projektteam.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'anw_hinweis_2_confirmed';
UPDATE fields x SET description = 'QE support identification and systematic processing of services in project team.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'anw_hinweis_3_confirmed';
UPDATE fields x SET description = 'Eigenverantwortliche Anwendung and projektspezifische Anpassung confirmed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'anw_hinweis_4_confirmed';
UPDATE fields x SET description = 'Strict copying and re-use of previously executed procedures will no longer meet the requirement for economic operation of a total system; rethinking is required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'grundsatz_avoid_strict_copying';
UPDATE fields x SET description = 'The planning engineering offices should be the drivers of new, forward-looking and sustainable approaches; in return, the client must set up projects so that this is possible.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'grundsatz_engineers_as_drivers';
UPDATE fields x SET description = 'All project participants must show greater openness and flexibility for innovative approaches to face shortage of skilled labour and changing resource availability.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'grundsatz_innovation_openness';
UPDATE fields x SET description = 'The economically efficient operating phase (lifecycle consideration) is an essential goal of planning and construction activities and is considered already during overall-system concept development.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'grundsatz_lifecycle_focus';
UPDATE fields x SET description = 'Kleinere kommunale Betriebe and similar: first overall system consideration including economic comparison, only then define single projects.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'grundsatz_two_step_followed';
UPDATE fields x SET description = 'Plan 3: Mehrfachauswahl über die vier gedruckten Anwendungshinweise (L200 / L202 / L204 / L206) neben den Booleans anw_hinweis_1…4_confirmed (REQ-02 hat eine leere Bedingung — Vorschlag STAGED m820_3-G-5; Ablösung der Booleans m820_3-J-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'anwendungshinweise';
UPDATE fields x SET description = '§ 3 (PDF S. 12): „Kleinere kommunale Betriebe haben die Möglichkeit, sich durch externe Fachexpertise unterstützen zu lassen. Hier ist die Zweistufigkeit erforderlich; d. h. zunächst eine Gesamtsystembetrachtung, inklusive Abwägung der Wirtschaftlichkeit, zu erstellen und erst dann Einzelprojekte zu definieren, die den langfristigen Bedarf auch wirklich decken.“ Ja = die Frage „Zweistufiger Ansatz angewandt“ wird gestellt und von REQ-05 (Warnung) geprüft. Nein (z. B. privater Auftraggeber, größerer Betrieb) = die Pflicht gilt nicht, die Frage ist ausgeblendet. Pflichtangabe.
[EN] § 3: "Smaller municipal operators may draw on external expertise. Here the two-stage approach is required …" Yes = the question "two-stage approach applied" is asked and checked by REQ-05 (warning). No (e.g. a private client, a larger operator) = the duty does not apply and the question is hidden. Required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'kleiner_kommunaler_betrieb';
UPDATE compliance_requirements x SET description = 'Die vier Anwendungshinweise (§ 1, PDF S. 9), z. B. „Im konkreten Projekt werden aus den Qualitätselementen die projektspezifischen Anforderungen und Aufgabenlisten, inklusive Zuständigkeiten, vom Anwendenden entwickelt und in Arbeitsunterlagen (beispielsweise Checklisten) dokumentiert.“ und „Eine Vervollständigung an den jeweiligen Projektaufgaben wird im Projektteam durchgeführt.“ — zur Kenntnis genommen (die vier Fragen dieses Blatts). Das Merkblatt druckt Hinweise, keine Pflicht zur Kenntnisnahme: Warnung, keine Blockade. Vorher leere Bedingung auf M8203-01.
[EN] The four application notes (§ 1), e.g. "In the specific project the user develops the project-specific requirements and task lists, including responsibilities, from the quality elements and documents them in working papers (e.g. checklists)." and "Completion for the respective project tasks is carried out in the project team." — acknowledged (the four questions of this sheet). The Merkblatt prints notes, not a duty to acknowledge: warning, no block. Was an empty condition on M8203-01.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.code = 'REQ-02';
UPDATE compliance_requirements x SET description = '§ 3 (PDF S. 12): „Kleinere kommunale Betriebe haben die Möglichkeit, sich durch externe Fachexpertise unterstützen zu lassen. Hier ist die Zweistufigkeit erforderlich; d. h. zunächst eine Gesamtsystembetrachtung, inklusive Abwägung der Wirtschaftlichkeit, zu erstellen und erst dann Einzelprojekte zu definieren, die den langfristigen Bedarf auch wirklich decken.“ Gilt nur, wenn der Auftraggeber ein kleinerer kommunaler Betrieb ist (Frage auf diesem Blatt). Schweregrad Warnung unverändert — das gedruckte „erforderlich“ spräche für eine Blockade (Freigabe-Entscheidung, Sign-off). Vorher leere Bedingung auf M8203-04.
[EN] § 3: "Smaller municipal operators may draw on external expertise. Here the two-stage approach is required, i.e. first an overall-system review including a weighing of economic efficiency, and only then the definition of single projects that really meet the long-term demand." Applies only when the client is a smaller municipal operator (question on this sheet). Severity warning unchanged — the printed "erforderlich" (required) would support a block (owner''s sign-off). Was an empty condition on M8203-04.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.code = 'REQ-05';
UPDATE fields x SET description = 'User confirms the structured planning process from Bild 1 (Konzept Gesamtsystem → Einzelprojekte) is the governing structure.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'bild1_acknowledged';
UPDATE fields x SET description = 'Step 1 of the Bild 1 process flow: Bedarfsplanung Konzept (overall-system needs planning) — the first step before any Einzelprojekt is launched.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'bild1_step_1_bedarfsplanung_konzept';
UPDATE fields x SET description = 'Step 2: Konzept für das Gesamtsystem — develops the actual concept; single measures and the investments they need are often avoided by this system-level consideration.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'bild1_step_2_konzept_gesamtsystem';
UPDATE fields x SET description = 'Step 3: All single projects required to realise the overall measure are identified.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'bild1_step_3_identifikation_projekte';
UPDATE fields x SET description = 'Step 4: Each identified project then runs through its own lifecycle: Bedarfsplanung Projekt → Planung → Ausführungsvorbereitung → Ausführung → Inbetriebnahme/Abnahme → Projektabschluss.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'bild1_step_4_einzelprojekt_lifecycle';
UPDATE fields x SET description = 'Awareness that DWA-M 820-3 is classified KA1 (indirect link to climate adaptation).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'klimakennung_ka1';
UPDATE fields x SET description = 'Awareness that DWA-M 820-3 is classified KS1 (indirect link to climate-protection parameters).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'klimakennung_ks1';
UPDATE fields x SET description = 'User acknowledges the regulation''s definition of ''Phase'' (clearly defined section of total project with start and end).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'phase_definition_acknowledged';
UPDATE fields x SET description = 'User acknowledges Phasenziele definition (results to be achieved after each LPH).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'phasenziele_definition_acknowledged';
UPDATE fields x SET description = 'User acknowledges Projektziele definition (total of individual goals to be achieved; per DIN 18205:2016 in 4 categories).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'projektziele_definition_acknowledged';
UPDATE fields x SET description = 'User acknowledges QE definition (defined service components whose fulfilment is verifiable and required for Phasenziele).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'qe_definition_acknowledged';
UPDATE fields x SET description = 'All interacting facility parts (e.g. Kläranlagen, Kanäle, Niederschlagswasserbehandlung) are considered as a whole within the Konzept Gesamtsystem.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'rahmen_system_aggregation_acknowledged';
UPDATE fields x SET description = 'A careful analysis of the existing state provides valid foundations for the concept to be developed; single measures and the investments they require can often be avoided through such consideration.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'rahmen_valid_existing_data_basis';
UPDATE fields x SET description = 'The regulation itself notes that direct cost and/or environmental impacts are not expected from applying this Merkblatt; consistent application improves project workflows and reduces lifecycle costs.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'vorwort_indirect_cost_env_impact';
UPDATE compliance_requirements x SET description = '§ 2.1 Definitionen (PDF S. 10): „Die Begriffe, die im Abschnitt 3 des Merkblatts DWA-M 820-1:2020 und Abschnitt 2 des Merkblatts DWA-M 820-2:2023 enthalten sind, gelten inhaltlich unverändert auch in diesem dritten Teil.“ — die vier Begriffe Phase, Phasenziele, Projektziele, Qualitätselemente zur Kenntnis genommen (die vier Fragen dieses Blatts). Keine gedruckte Pflicht: Warnung. Vorher leere Bedingung auf M8203-01.
[EN] § 2.1 definitions: "The terms contained in section 3 of DWA-M 820-1:2020 and section 2 of DWA-M 820-2:2023 apply unchanged in content in this third part as well." — the four terms phase, phase goals, project goals, quality elements acknowledged (the four questions of this sheet). No printed duty: warning. Was an empty condition on M8203-01.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.code = 'REQ-03';
UPDATE compliance_requirements x SET description = 'Project adopts the Bild 1 (Konzept Gesamtsystem → Einzelprojekte) process structure as governing.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.code = 'REQ-04';
UPDATE fields x SET description = 'Status assessment for Phasenziel 1 of §5.2 Bedarfsplanung Konzept.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.symbol = 'pz_52_1_status';
UPDATE fields x SET description = 'Status assessment for Phasenziel 2 of §5.2 Bedarfsplanung Konzept.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.symbol = 'pz_52_2_status';
UPDATE fields x SET description = 'Status assessment for Phasenziel 3 of §5.2 Bedarfsplanung Konzept.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.symbol = 'pz_52_3_status';
UPDATE fields x SET description = 'Status assessment for Phasenziel 4 of §5.2 Bedarfsplanung Konzept.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.symbol = 'pz_52_4_status';
UPDATE fields x SET description = 'Status assessment for Phasenziel 5 of §5.2 Bedarfsplanung Konzept.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.symbol = 'pz_52_5_status';
UPDATE fields x SET description = '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Pflicht über REQ-06-2, sobald ein Phasenziel dieses Blatts „Nicht erreicht“ oder „Teilweise erreicht“ ist; „Erreicht“, „Nicht zutreffend“ und „Phase noch nicht erreicht“ lösen die Prüfung nicht aus. Ja = die Prüfung ist durchgeführt und die Risikoanalyse (ob und wie das Projekt fortgeführt wird) dokumentiert; das Ergebnis gehört in „Projektstopp erforderlich“ (M8203-24).
[EN] § 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Required through REQ-06-2 as soon as a phase goal of this sheet is "not met" or "partially met"; "met", "not applicable" and "phase not reached yet" do not trigger it. Yes = the review is done and the risk analysis (whether and how the project continues) is documented; its result belongs in "Projektstopp required" (M8203-24).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.symbol = 'pz_52_projektstopp_risikoanalyse';
UPDATE compliance_requirements x SET description = 'Alle Phasenziele von § 5.2 Bedarfsplanung Konzept (Status je Ziel auf diesem Blatt). Bestanden: Erreicht, Teilweise erreicht, Nicht zutreffend oder Phase noch nicht erreicht; „Nicht erreicht“ blockiert. Gilt nur für den Pfad „Gesamtsystem“ (Projekttyp Gesamtsystem oder Beides) — L321 (PDF S. 13): „Die Aufteilung in „Konzept für das Gesamtsystem“ und „Projekte“ ist dabei eine elementare Grundlage.“; ohne Projekttyp (M8203-01) wartet die Prüfung. „Phase noch nicht erreicht“: Phasenziele sind „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind“ (§ 2.1, PDF S. 10); die Bewertung liegt beim Projektteam (L202, PDF S. 9: „Eine Vervollständigung an den jeweiligen Projektaufgaben wird im Projektteam durchgeführt.“). „Teilweise erreicht“ besteht hier, löst aber die Projektstopp-Prüfung REQ-06-2 aus (§ 3, PDF S. 12: „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich.“).
[EN] All phase goals of § 5.2 needs planning (concept) (status per goal on this sheet). Pass: met, partially met, not applicable or phase not reached yet; "not met" blocks. Applies only to the "overall system" path (project type gesamtsystem or both) — L321: "The division into ''concept for the overall system'' and ''projects'' is an elementary basis."; without a project type (M8203-01) the check waits. "Phase not reached yet": phase goals are "results to be achieved after completion of the respective service phase" (§ 2.1); the assessment is the project team''s (L202). "Partially met" passes here but triggers the Projektstopp review REQ-06-2 (§ 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued.").' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.code = 'REQ-06';
UPDATE compliance_requirements x SET description = '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Modalverben „ist … erforderlich“ / „muss“ → Blockade. Ist ein Phasenziel dieses Blatts „Nicht erreicht“ oder „Teilweise erreicht“ („nur unvollständig erreicht“), muss „Projektstopp-Prüfung mit Risikoanalyse durchgeführt“ (dieses Blatt) bejaht sein. „Phase noch nicht erreicht“ und „Nicht zutreffend“ lösen nichts aus.
[EN] § 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Modal verbs "ist … erforderlich" (is required) / "muss" (must) → block. When a phase goal of this sheet is "not met" or "partially met" ("only incompletely achieved"), "Projektstopp review with risk analysis carried out" (this sheet) must be Yes. "Phase not reached yet" and "not applicable" trigger nothing.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.code = 'REQ-06-2';
UPDATE compliance_requirements x SET description = 'Mindestens ein Phasenziel dieses Blatts ist „Phase noch nicht erreicht“. Bitte bestätigen, dass die Phase wirklich noch bevorsteht; eine abgeschlossene Phase muss bewertet werden (Erreicht / Teilweise erreicht / Nicht erreicht / Nicht zutreffend). § 2.1 (PDF S. 10): Phasenziele sind „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind“. Warnung, keine Blockade (Entscheidung Sign-off).
[EN] At least one phase goal of this sheet is "phase not reached yet". Please confirm that the phase really is still ahead; a closed phase must be rated (met / partially met / not met / not applicable). § 2.1: phase goals are "results to be achieved after completion of the respective service phase". Warning, not a block (sign-off ruling).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.code = 'REQ-06-3';
UPDATE fields x SET description = 'Status assessment for Phasenziel 1 of §5.3 Konzept Gesamtsystem.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.symbol = 'pz_53_1_status';
UPDATE fields x SET description = 'Status assessment for Phasenziel 2 of §5.3 Konzept Gesamtsystem.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.symbol = 'pz_53_2_status';
UPDATE fields x SET description = 'Status assessment for Phasenziel 3 of §5.3 Konzept Gesamtsystem.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.symbol = 'pz_53_3_status';
UPDATE fields x SET description = 'Status assessment for Phasenziel 4 of §5.3 Konzept Gesamtsystem.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.symbol = 'pz_53_4_status';
UPDATE fields x SET description = 'Status assessment for Phasenziel 5 of §5.3 Konzept Gesamtsystem.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.symbol = 'pz_53_5_status';
UPDATE fields x SET description = '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Pflicht über REQ-07-2, sobald ein Phasenziel dieses Blatts „Nicht erreicht“ oder „Teilweise erreicht“ ist; „Erreicht“, „Nicht zutreffend“ und „Phase noch nicht erreicht“ lösen die Prüfung nicht aus. Ja = die Prüfung ist durchgeführt und die Risikoanalyse (ob und wie das Projekt fortgeführt wird) dokumentiert; das Ergebnis gehört in „Projektstopp erforderlich“ (M8203-24).
[EN] § 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Required through REQ-07-2 as soon as a phase goal of this sheet is "not met" or "partially met"; "met", "not applicable" and "phase not reached yet" do not trigger it. Yes = the review is done and the risk analysis (whether and how the project continues) is documented; its result belongs in "Projektstopp required" (M8203-24).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.symbol = 'pz_53_projektstopp_risikoanalyse';
UPDATE compliance_requirements x SET description = 'Alle Phasenziele von § 5.3 Konzept (Gesamtsystem) (Status je Ziel auf diesem Blatt). Bestanden: Erreicht, Teilweise erreicht, Nicht zutreffend oder Phase noch nicht erreicht; „Nicht erreicht“ blockiert. Gilt nur für den Pfad „Gesamtsystem“ (Projekttyp Gesamtsystem oder Beides) — L321 (PDF S. 13): „Die Aufteilung in „Konzept für das Gesamtsystem“ und „Projekte“ ist dabei eine elementare Grundlage.“; ohne Projekttyp (M8203-01) wartet die Prüfung. „Phase noch nicht erreicht“: Phasenziele sind „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind“ (§ 2.1, PDF S. 10); die Bewertung liegt beim Projektteam (L202, PDF S. 9: „Eine Vervollständigung an den jeweiligen Projektaufgaben wird im Projektteam durchgeführt.“). „Teilweise erreicht“ besteht hier, löst aber die Projektstopp-Prüfung REQ-07-2 aus (§ 3, PDF S. 12: „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich.“).
[EN] All phase goals of § 5.3 concept (overall system) (status per goal on this sheet). Pass: met, partially met, not applicable or phase not reached yet; "not met" blocks. Applies only to the "overall system" path (project type gesamtsystem or both) — L321: "The division into ''concept for the overall system'' and ''projects'' is an elementary basis."; without a project type (M8203-01) the check waits. "Phase not reached yet": phase goals are "results to be achieved after completion of the respective service phase" (§ 2.1); the assessment is the project team''s (L202). "Partially met" passes here but triggers the Projektstopp review REQ-07-2 (§ 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued.").' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.code = 'REQ-07';
UPDATE compliance_requirements x SET description = '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Modalverben „ist … erforderlich“ / „muss“ → Blockade. Ist ein Phasenziel dieses Blatts „Nicht erreicht“ oder „Teilweise erreicht“ („nur unvollständig erreicht“), muss „Projektstopp-Prüfung mit Risikoanalyse durchgeführt“ (dieses Blatt) bejaht sein. „Phase noch nicht erreicht“ und „Nicht zutreffend“ lösen nichts aus.
[EN] § 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Modal verbs "ist … erforderlich" (is required) / "muss" (must) → block. When a phase goal of this sheet is "not met" or "partially met" ("only incompletely achieved"), "Projektstopp review with risk analysis carried out" (this sheet) must be Yes. "Phase not reached yet" and "not applicable" trigger nothing.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.code = 'REQ-07-2';
UPDATE compliance_requirements x SET description = 'Mindestens ein Phasenziel dieses Blatts ist „Phase noch nicht erreicht“. Bitte bestätigen, dass die Phase wirklich noch bevorsteht; eine abgeschlossene Phase muss bewertet werden (Erreicht / Teilweise erreicht / Nicht erreicht / Nicht zutreffend). § 2.1 (PDF S. 10): Phasenziele sind „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind“. Warnung, keine Blockade (Entscheidung Sign-off).
[EN] At least one phase goal of this sheet is "phase not reached yet". Please confirm that the phase really is still ahead; a closed phase must be rated (met / partially met / not met / not applicable). § 2.1: phase goals are "results to be achieved after completion of the respective service phase". Warning, not a block (sign-off ruling).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.code = 'REQ-07-3';
UPDATE fields x SET description = 'Status assessment for Phasenziel 1 of §5.4 Identifikation von Projekten.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-06' AND x.symbol = 'pz_54_1_status';
UPDATE fields x SET description = 'Status assessment for Phasenziel 2 of §5.4 Identifikation von Projekten.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-06' AND x.symbol = 'pz_54_2_status';
UPDATE fields x SET description = 'Status assessment for Phasenziel 3 of §5.4 Identifikation von Projekten.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-06' AND x.symbol = 'pz_54_3_status';
UPDATE fields x SET description = '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Pflicht über REQ-08-2, sobald ein Phasenziel dieses Blatts „Nicht erreicht“ oder „Teilweise erreicht“ ist; „Erreicht“, „Nicht zutreffend“ und „Phase noch nicht erreicht“ lösen die Prüfung nicht aus. Ja = die Prüfung ist durchgeführt und die Risikoanalyse (ob und wie das Projekt fortgeführt wird) dokumentiert; das Ergebnis gehört in „Projektstopp erforderlich“ (M8203-24).
