[EN] At least one phase goal of this sheet is "phase not reached yet". Please confirm that the phase really is still ahead; a closed phase must be rated (met / partially met / not met / not applicable). § 2.1: phase goals are "results to be achieved after completion of the respective service phase". Warning, not a block (sign-off ruling).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-06' AND x.code = 'REQ-08-3';
UPDATE fields x SET description = 'Date when this QE assessment was performed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_assessment_date';
UPDATE fields x SET description = 'Person/role who performed the assessment.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_assessor';
UPDATE fields x SET description = 'Whether corrective actions are required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_corrective_actions';
UPDATE fields x SET description = 'Description of critical gaps that may affect Phasenziele achievement. Per §3 Grundsätze, unmet Phasenziele may trigger Projektstopp review.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_critical_gaps';
UPDATE fields x SET description = 'Overall fulfilment rate computed from Y/P/N counts.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_fulfilment_pct';
UPDATE fields x SET description = 'Count of QE items rated N (Not fulfilled).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_items_n';
UPDATE fields x SET description = 'Count of QE items rated N/A (de-selected project-specifically per Vorwort p.3 / §1 Anwendungshinweise).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_items_na';
UPDATE fields x SET description = 'Count of QE items rated P (Partially fulfilled).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_items_p';
UPDATE fields x SET description = 'Total QE items in Anhang A.1; verbatim count 15.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_items_total';
UPDATE fields x SET description = 'Count of QE items rated Y (Yes/Fulfilled).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_items_y';
UPDATE fields x SET description = 'Plan 3: Zeilen je gedrucktem Kriterium aus QE_A1 (15 Kriterien Nr. 1–15; Nr. → Kriterium / Hinweise aus dem Katalog, Bewertung Y / P / N / NA, Nachweis, Bemerkung); Zählungen → qe52_items_y_calc / qe52_items_p_calc / qe52_items_n_calc / qe52_items_na_calc / qe52_items_rated (M8203-07-D1 … -D5), Anteile je Bewertung → qe52_share_y_pct / qe52_share_p_pct / qe52_share_n_pct / qe52_share_na_pct (M8203-07-D6 … -D9, Nenner qe52_items_total); Erfüllungsgrad qe52_fulfilment_pct bleibt Eingabe (P-Gewicht / NA-Behandlung nicht gedruckt — m820_3-F-1). Sichtbar für project_type gesamtsystem / both — wirksam erst nach m820_3-C-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_items';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-07-D5 (count_rows über qe52_items); die manuellen Zählfelder qe52_items_y/p/n/na bleiben Eingaben — Ablösung STAGED (m820_3-D-1), Gate-Umbindung STAGED (m820_3-G-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_items_rated';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-07-D1 (count_rows mit rating == ''y'' über qe52_items); die manuellen Zählfelder qe52_items_y/p/n/na bleiben Eingaben — Ablösung STAGED (m820_3-D-1), Gate-Umbindung STAGED (m820_3-G-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_items_y_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-07-D2 (count_rows mit rating == ''p'' über qe52_items); die manuellen Zählfelder qe52_items_y/p/n/na bleiben Eingaben — Ablösung STAGED (m820_3-D-1), Gate-Umbindung STAGED (m820_3-G-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_items_p_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-07-D3 (count_rows mit rating == ''n'' über qe52_items); die manuellen Zählfelder qe52_items_y/p/n/na bleiben Eingaben — Ablösung STAGED (m820_3-D-1), Gate-Umbindung STAGED (m820_3-G-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_items_n_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-07-D4 (count_rows mit rating == ''na'' über qe52_items); die manuellen Zählfelder qe52_items_y/p/n/na bleiben Eingaben — Ablösung STAGED (m820_3-D-1), Gate-Umbindung STAGED (m820_3-G-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_items_na_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-07-D6 (count_rows mit rating == ''y'' · 100 / items_total über qe52_items); die manuellen Zählfelder qe52_items_y/p/n/na bleiben Eingaben — Ablösung STAGED (m820_3-D-1), Gate-Umbindung STAGED (m820_3-G-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-07' AND x.symbol = 'qe52_share_y_pct';
