UPDATE fields x SET description = '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Pflicht über REQ-10-2, sobald ein Phasenziel dieses Blatts „Nicht erreicht“ oder „Teilweise erreicht“ ist; „Erreicht“, „Nicht zutreffend“ und „Phase noch nicht erreicht“ lösen die Prüfung nicht aus. Ja = die Prüfung ist durchgeführt und die Risikoanalyse (ob und wie das Projekt fortgeführt wird) dokumentiert; das Ergebnis gehört in „Projektstopp erforderlich“ (M8203-24).
[EN] § 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Required through REQ-10-2 as soon as a phase goal of this sheet is "not met" or "partially met"; "met", "not applicable" and "phase not reached yet" do not trigger it. Yes = the review is done and the risk analysis (whether and how the project continues) is documented; its result belongs in "Projektstopp required" (M8203-24).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-13' AND x.symbol = 'pz_63_projektstopp_risikoanalyse';
UPDATE equations x SET description = 'Plan 3: Anzahl der Kriterien mit Bewertung Y — erfüllt im Register qe63b_items, nur Zeilen Teil 2 (Nr. 22–40) (in_teil == 1); Zwilling des manuellen qe63b_items_y (Ablösung STAGED m820_3-D-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-13' AND x.equation_number = 'M8203-13-D1';
