UPDATE equations x SET description = 'Plan 3: Anzahl der Kriterien mit Bewertung N — nicht erfüllt im Register qe63b_items, nur Zeilen Teil 2 (Nr. 22–40) (in_teil == 1); Zwilling des manuellen qe63b_items_n (Ablösung STAGED m820_3-D-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-13' AND x.equation_number = 'M8203-13-D3';
UPDATE equations x SET description = 'Plan 3: Anzahl der Kriterien mit Bewertung NA — nicht zutreffend im Register qe63b_items, nur Zeilen Teil 2 (Nr. 22–40) (in_teil == 1); Zwilling des manuellen qe63b_items_na (Ablösung STAGED m820_3-D-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-13' AND x.equation_number = 'M8203-13-D4';
UPDATE equations x SET description = 'Plan 3: Anzahl vollständig bewerteter Zeilen im Register qe63b_items, nur Zeilen Teil 2 (Nr. 22–40) (in_teil == 1) — Vollständigkeit = 19 (die gedruckten Kriterien Nr. 22–40); Umbindung der Vollständigkeitsgates REQ-15 … REQ-24 (y + p + n + na == total) STAGED (m820_3-G-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-13' AND x.equation_number = 'M8203-13-D5';
