UPDATE fields x SET description = 'Plan 3: Zeilen je gedrucktem Kriterium aus QE_B3 (17 Kriterien Nr. 1–17; Nr. → Kriterium / Hinweise aus dem Katalog, Bewertung Y / P / N / NA, Nachweis, Bemerkung); Zählungen → qe64a_items_y_calc / qe64a_items_p_calc / qe64a_items_n_calc / qe64a_items_na_calc / qe64a_items_rated (M8203-14-D1 … -D5), Anteile je Bewertung → qe64a_share_y_pct / qe64a_share_p_pct / qe64a_share_n_pct / qe64a_share_na_pct (M8203-14-D6 … -D9, Nenner qe64a_items_total); Erfüllungsgrad qe64a_fulfilment_pct bleibt Eingabe (P-Gewicht / NA-Behandlung nicht gedruckt — m820_3-F-1). Sichtbar für project_type einzelprojekt / both — wirksam erst nach m820_3-C-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-14' AND x.symbol = 'qe64a_items';
