UPDATE fields x SET description = 'Plan 3: Zeilen je gedrucktem Kriterium aus QE_B4 (34 Kriterien Nr. 1–34; Nr. → Kriterium / Hinweise aus dem Katalog, Bewertung Y / P / N / NA, Nachweis, Bemerkung); Zählungen → qe65_items_y_calc / qe65_items_p_calc / qe65_items_n_calc / qe65_items_na_calc / qe65_items_rated (M8203-16-D1 … -D5), Anteile je Bewertung → qe65_share_y_pct / qe65_share_p_pct / qe65_share_n_pct / qe65_share_na_pct (M8203-16-D6 … -D9, Nenner qe65_items_total); Erfüllungsgrad qe65_fulfilment_pct bleibt Eingabe (P-Gewicht / NA-Behandlung nicht gedruckt — m820_3-F-1). Sichtbar für project_type einzelprojekt / both — wirksam erst nach m820_3-C-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.symbol = 'qe65_items';
