UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-16-D4 (count_rows mit rating == ''na'' über qe65_items); die manuellen Zählfelder qe65_items_y/p/n/na bleiben Eingaben — Ablösung STAGED (m820_3-D-1), Gate-Umbindung STAGED (m820_3-G-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.symbol = 'qe65_items_na_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-16-D6 (count_rows mit rating == ''y'' · 100 / items_total über qe65_items); die manuellen Zählfelder qe65_items_y/p/n/na bleiben Eingaben — Ablösung STAGED (m820_3-D-1), Gate-Umbindung STAGED (m820_3-G-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.symbol = 'qe65_share_y_pct';
