UPDATE equations x SET description = 'Plan 3: Anzahl der Kriterien mit Bewertung P — teilweise erfüllt im Register qe65_items; Zwilling des manuellen qe65_items_p (Ablösung STAGED m820_3-D-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.equation_number = 'M8203-16-D2';
UPDATE equations x SET description = 'Plan 3: Anzahl der Kriterien mit Bewertung N — nicht erfüllt im Register qe65_items; Zwilling des manuellen qe65_items_n (Ablösung STAGED m820_3-D-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.equation_number = 'M8203-16-D3';
UPDATE equations x SET description = 'Plan 3: Anzahl der Kriterien mit Bewertung NA — nicht zutreffend im Register qe65_items; Zwilling des manuellen qe65_items_na (Ablösung STAGED m820_3-D-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.equation_number = 'M8203-16-D4';
UPDATE equations x SET description = 'Plan 3: Anzahl vollständig bewerteter Zeilen im Register qe65_items — Vollständigkeit = 34 (die gedruckten Kriterien Nr. 1–34); Umbindung der Vollständigkeitsgates REQ-15 … REQ-24 (y + p + n + na == total) STAGED (m820_3-G-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.equation_number = 'M8203-16-D5';
UPDATE equations x SET description = 'Plan 3: Anteil der Kriterien mit Bewertung Y — erfüllt an den 34 gedruckten Kriterien (Nenner qe65_items_total); kein Erfüllungsgrad — P-Gewicht / NA-Behandlung nicht gedruckt (m820_3-F-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.equation_number = 'M8203-16-D6';
UPDATE equations x SET description = 'Plan 3: Anteil der Kriterien mit Bewertung P — teilweise erfüllt an den 34 gedruckten Kriterien (Nenner qe65_items_total); kein Erfüllungsgrad — P-Gewicht / NA-Behandlung nicht gedruckt (m820_3-F-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.equation_number = 'M8203-16-D7';
UPDATE equations x SET description = 'Plan 3: Anteil der Kriterien mit Bewertung N — nicht erfüllt an den 34 gedruckten Kriterien (Nenner qe65_items_total); kein Erfüllungsgrad — P-Gewicht / NA-Behandlung nicht gedruckt (m820_3-F-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.equation_number = 'M8203-16-D8';
UPDATE equations x SET description = 'Plan 3: Anteil der Kriterien mit Bewertung NA — nicht zutreffend an den 34 gedruckten Kriterien (Nenner qe65_items_total); kein Erfüllungsgrad — P-Gewicht / NA-Behandlung nicht gedruckt (m820_3-F-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.equation_number = 'M8203-16-D9';
UPDATE compliance_requirements x SET description = 'Alle Phasenziele von § 6.5 Ausführung (Status je Ziel auf diesem Blatt). Bestanden: Erreicht, Teilweise erreicht, Nicht zutreffend oder Phase noch nicht erreicht; „Nicht erreicht“ blockiert. Gilt nur für den Pfad „Projekte“ (Projekttyp Einzelprojekt oder Beides) — L321 (PDF S. 13): „Die Aufteilung in „Konzept für das Gesamtsystem“ und „Projekte“ ist dabei eine elementare Grundlage.“; ohne Projekttyp (M8203-01) wartet die Prüfung. „Phase noch nicht erreicht“: Phasenziele sind „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind“ (§ 2.1, PDF S. 10); die Bewertung liegt beim Projektteam (L202, PDF S. 9: „Eine Vervollständigung an den jeweiligen Projektaufgaben wird im Projektteam durchgeführt.“). „Teilweise erreicht“ besteht hier, löst aber die Projektstopp-Prüfung REQ-12-2 aus (§ 3, PDF S. 12: „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich.“).
[EN] All phase goals of § 6.5 execution (status per goal on this sheet). Pass: met, partially met, not applicable or phase not reached yet; "not met" blocks. Applies only to the "projects" path (project type einzelprojekt or both) — L321: "The division into ''concept for the overall system'' and ''projects'' is an elementary basis."; without a project type (M8203-01) the check waits. "Phase not reached yet": phase goals are "results to be achieved after completion of the respective service phase" (§ 2.1); the assessment is the project team''s (L202). "Partially met" passes here but triggers the Projektstopp review REQ-12-2 (§ 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued.").' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.code = 'REQ-12';
UPDATE compliance_requirements x SET description = '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Modalverben „ist … erforderlich“ / „muss“ → Blockade. Ist ein Phasenziel dieses Blatts „Nicht erreicht“ oder „Teilweise erreicht“ („nur unvollständig erreicht“), muss „Projektstopp-Prüfung mit Risikoanalyse durchgeführt“ (dieses Blatt) bejaht sein. „Phase noch nicht erreicht“ und „Nicht zutreffend“ lösen nichts aus.
[EN] § 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Modal verbs "ist … erforderlich" (is required) / "muss" (must) → block. When a phase goal of this sheet is "not met" or "partially met" ("only incompletely achieved"), "Projektstopp review with risk analysis carried out" (this sheet) must be Yes. "Phase not reached yet" and "not applicable" trigger nothing.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.code = 'REQ-12-2';
UPDATE compliance_requirements x SET description = 'Mindestens ein Phasenziel dieses Blatts ist „Phase noch nicht erreicht“. Bitte bestätigen, dass die Phase wirklich noch bevorsteht; eine abgeschlossene Phase muss bewertet werden (Erreicht / Teilweise erreicht / Nicht erreicht / Nicht zutreffend). § 2.1 (PDF S. 10): Phasenziele sind „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind“. Warnung, keine Blockade (Entscheidung Sign-off).
[EN] At least one phase goal of this sheet is "phase not reached yet". Please confirm that the phase really is still ahead; a closed phase must be rated (met / partially met / not met / not applicable). § 2.1: phase goals are "results to be achieved after completion of the respective service phase". Warning, not a block (sign-off ruling).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-16' AND x.code = 'REQ-12-3';
