UPDATE fields x SET description = 'Plan 3: Zeilen je gedrucktem Kriterium aus QE_B5 (10 Kriterien Nr. 1–10; Nr. → Kriterium / Hinweise aus dem Katalog, Bewertung Y / P / N / NA, Nachweis, Bemerkung); Zählungen → qe66_items_y_calc / qe66_items_p_calc / qe66_items_n_calc / qe66_items_na_calc / qe66_items_rated (M8203-17-D1 … -D5), Anteile je Bewertung → qe66_share_y_pct / qe66_share_p_pct / qe66_share_n_pct / qe66_share_na_pct (M8203-17-D6 … -D9, Nenner qe66_items_total); Erfüllungsgrad qe66_fulfilment_pct bleibt Eingabe (P-Gewicht / NA-Behandlung nicht gedruckt — m820_3-F-1). Sichtbar für project_type einzelprojekt / both — wirksam erst nach m820_3-C-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-17' AND x.symbol = 'qe66_items';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-17-D5 (count_rows über qe66_items); die manuellen Zählfelder qe66_items_y/p/n/na bleiben Eingaben — Ablösung STAGED (m820_3-D-1), Gate-Umbindung STAGED (m820_3-G-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-17' AND x.symbol = 'qe66_items_rated';
