UPDATE equations x SET description = 'Plan 3: Anteil der Kriterien mit Bewertung P — teilweise erfüllt an den 6 gedruckten Kriterien (Nenner qe67_items_total); kein Erfüllungsgrad — P-Gewicht / NA-Behandlung nicht gedruckt (m820_3-F-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-18' AND x.equation_number = 'M8203-18-D7';
UPDATE equations x SET description = 'Plan 3: Anteil der Kriterien mit Bewertung N — nicht erfüllt an den 6 gedruckten Kriterien (Nenner qe67_items_total); kein Erfüllungsgrad — P-Gewicht / NA-Behandlung nicht gedruckt (m820_3-F-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-18' AND x.equation_number = 'M8203-18-D8';
UPDATE equations x SET description = 'Plan 3: Anteil der Kriterien mit Bewertung NA — nicht zutreffend an den 6 gedruckten Kriterien (Nenner qe67_items_total); kein Erfüllungsgrad — P-Gewicht / NA-Behandlung nicht gedruckt (m820_3-F-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-18' AND x.equation_number = 'M8203-18-D9';
UPDATE compliance_requirements x SET description = 'Alle Phasenziele von § 6.7 Projektabschluss (Status je Ziel auf diesem Blatt). Bestanden: Erreicht, Teilweise erreicht, Nicht zutreffend oder Phase noch nicht erreicht; „Nicht erreicht“ blockiert. Gilt nur für den Pfad „Projekte“ (Projekttyp Einzelprojekt oder Beides) — L321 (PDF S. 13): „Die Aufteilung in „Konzept für das Gesamtsystem“ und „Projekte“ ist dabei eine elementare Grundlage.“; ohne Projekttyp (M8203-01) wartet die Prüfung. „Phase noch nicht erreicht“: Phasenziele sind „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind“ (§ 2.1, PDF S. 10); die Bewertung liegt beim Projektteam (L202, PDF S. 9: „Eine Vervollständigung an den jeweiligen Projektaufgaben wird im Projektteam durchgeführt.“). „Teilweise erreicht“ besteht hier, löst aber die Projektstopp-Prüfung REQ-14-2 aus (§ 3, PDF S. 12: „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich.“).
[EN] All phase goals of § 6.7 project close-out (status per goal on this sheet). Pass: met, partially met, not applicable or phase not reached yet; "not met" blocks. Applies only to the "projects" path (project type einzelprojekt or both) — L321: "The division into ''concept for the overall system'' and ''projects'' is an elementary basis."; without a project type (M8203-01) the check waits. "Phase not reached yet": phase goals are "results to be achieved after completion of the respective service phase" (§ 2.1); the assessment is the project team''s (L202). "Partially met" passes here but triggers the Projektstopp review REQ-14-2 (§ 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued.").' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-18' AND x.code = 'REQ-14';
UPDATE compliance_requirements x SET description = '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Modalverben „ist … erforderlich“ / „muss“ → Blockade. Ist ein Phasenziel dieses Blatts „Nicht erreicht“ oder „Teilweise erreicht“ („nur unvollständig erreicht“), muss „Projektstopp-Prüfung mit Risikoanalyse durchgeführt“ (dieses Blatt) bejaht sein. „Phase noch nicht erreicht“ und „Nicht zutreffend“ lösen nichts aus.
[EN] § 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Modal verbs "ist … erforderlich" (is required) / "muss" (must) → block. When a phase goal of this sheet is "not met" or "partially met" ("only incompletely achieved"), "Projektstopp review with risk analysis carried out" (this sheet) must be Yes. "Phase not reached yet" and "not applicable" trigger nothing.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-18' AND x.code = 'REQ-14-2';
UPDATE compliance_requirements x SET description = 'Mindestens ein Phasenziel dieses Blatts ist „Phase noch nicht erreicht“. Bitte bestätigen, dass die Phase wirklich noch bevorsteht; eine abgeschlossene Phase muss bewertet werden (Erreicht / Teilweise erreicht / Nicht erreicht / Nicht zutreffend). § 2.1 (PDF S. 10): Phasenziele sind „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind“. Warnung, keine Blockade (Entscheidung Sign-off).
[EN] At least one phase goal of this sheet is "phase not reached yet". Please confirm that the phase really is still ahead; a closed phase must be rated (met / partially met / not met / not applicable). § 2.1: phase goals are "results to be achieved after completion of the respective service phase". Warning, not a block (sign-off ruling).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-18' AND x.code = 'REQ-14-3';
UPDATE compliance_requirements x SET description = '6 QE items of Anhang B.6 assessed with evidence.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-18' AND x.code = 'REQ-24';
UPDATE fields x SET description = 'AIA available and adapted to operating-phase data needs.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND x.symbol = 'aia_available';
UPDATE fields x SET description = 'BIM execution plan (BAP) defined and agreed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND x.symbol = 'bap_defined';
UPDATE fields x SET description = 'BIM-Projektdefinition complete.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND x.symbol = 'bim_project_definition_complete';
UPDATE fields x SET description = 'CDE platform and data-exchange agreements established.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND x.symbol = 'cde_platform_defined';
UPDATE fields x SET description = 'Bestandsmodell complete after project (Digital Twin).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND x.symbol = 'digital_twin_after_project';
UPDATE fields x SET description = '§ 7.2.1 (PDF S. 21): „Die digitale Planung, hier insbesondere die BIM-Methodik, kristallisiert sich mehr und mehr als Arbeitsinstrument und Methode heraus. Die digitale Kommunikation von Projektmodellen sowie die Integration der Planungsleistungen anderer Planungsgewerke sind in Vorbereitung oder bereits teilweise in der Umsetzung.“ § 7.5.2 (PDF S. 23): „Unter Projektkommunikation wird der Einsatz von Kommunikationsplattformen verstanden. Beim Einsatz der BIM-Planung stehen dafür Werkzeuge bereit und werden eingesetzt.“ § 7.1 (PDF S. 21): „Details zur BIM-Planung werden in einer DWA-Arbeitsgruppe für die Wasser- und Abwasserwirtschaft erarbeitet und in der Merkblattreihe DWA-M 860 dokumentiert.“ Ja = die BIM-Ziele gelten: § 7.2.2 (REQ-25), § 7.2.3 (REQ-26) auf diesem Blatt, § 7.5.2 (REQ-29) auf M8203-21. Nein = diese Fragen sind ausgeblendet und die Prüfungen nicht erforderlich. Bestandsdaten (§ 7.3), Datenrechte (§ 7.4) und Bürgerinformation (§ 7.5.3) gelten unabhängig davon. Pflichtangabe; ohne Antwort warten die drei Prüfungen.
[EN] § 7.2.1: "Digital planning, here in particular the BIM method, is increasingly emerging as a working tool and method. The digital communication of project models and the integration of the planning services of other trades are in preparation or already partly in practice." § 7.5.2: "… Where BIM planning is used, tools are available for this and are used." § 7.1: BIM details are documented in the DWA-M 860 series. Yes = the BIM goals apply: § 7.2.2 (REQ-25), § 7.2.3 (REQ-26) on this sheet, § 7.5.2 (REQ-29) on M8203-21. No = those questions are hidden and the checks not required. Existing-asset data (§ 7.3), data rights (§ 7.4) and public information (§ 7.5.3) apply regardless. Required; without an answer the three checks wait.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND x.symbol = 'digitale_methoden_bim_angewendet';
UPDATE compliance_requirements x SET description = '§ 7.2.2 Ziele (PDF S. 21): „Die BIM-Projektdefinition ist abgeschlossen.“ „Die AIA (Auftraggeberinformationsanforderungen) liegen vor.“ „Der BAP (BIM-Abwicklungsplan) ist definiert und abgestimmt.“ — nur wenn das Projekt mit digitaler Planung nach der BIM-Methodik abgewickelt wird (Frage auf diesem Blatt; § 7.2.1, PDF S. 21: „Die digitale Planung, hier insbesondere die BIM-Methodik, kristallisiert sich mehr und mehr als Arbeitsinstrument und Methode heraus.“).
[EN] § 7.2.2 goals: "The BIM project definition is completed." "The AIA (employer''s information requirements) are available." "The BAP (BIM execution plan) is defined and agreed." — only when the project is run with digital planning using the BIM method (question on this sheet; § 7.2.1: "Digital planning, here in particular the BIM method, is increasingly emerging as a working tool and method.").' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND x.code = 'REQ-25';
UPDATE compliance_requirements x SET description = '§ 7.2.3 Ziele (PDF S. 22): „Die erarbeiteten digitalen Modelle werden für alle Belange der Planungsphasen und der Ausführungsphase, samt Inbetriebnahme durchgängig angewendet und gepflegt.“ „Das Bestandsmodell ist nach Abschluss des Projekts fertiggestellt („Digital Twin“).“ — nur bei digitaler Planung nach der BIM-Methodik (Frage auf diesem Blatt).
[EN] § 7.2.3 goals: "The digital models developed are applied and maintained consistently for all aspects of the planning phases and the execution phase, including commissioning." "The as-built model is completed after the end of the project (''digital twin'')." — only with digital planning using the BIM method (question on this sheet).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND x.code = 'REQ-26';
UPDATE fields x SET description = 'Unambiguous Anlagenkennzeichnungssystem (AKZ) is the basis for asset management.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-20' AND x.symbol = 'akz_in_place';
UPDATE fields x SET description = 'Existing data are complete, current, and digital (georeferenced, vectorised) for the planning task.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-20' AND x.symbol = 'bestandsdaten_complete_digital';
UPDATE fields x SET description = 'Critical-infrastructure legal requirements assessed before project start.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-20' AND x.symbol = 'critical_infra_assessed';
UPDATE fields x SET description = 'Urheber- and Nutzungsrechte at digital data clarified; legal advice taken if needed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-20' AND x.symbol = 'digital_rights_clarified';
UPDATE compliance_requirements x SET description = '§ 7.3 Ziele (PDF S. 22–23): „Bestandsdaten sind in Bezug auf die bevorstehenden Planungsaufgaben vollständig, aktuell und digital (bspw. georeferenziert, vektorisiert, Bezugssystem) verfügbar.“ · „Grundlage dafür ist ein eindeutiges Anlagenkennzeichnungssystem (AKZ).“ · „Die Anforderungen der Gesetzgebung zur kritischen Infrastruktur wurden im Vorfeld abgeklärt und sind im Projekt berücksichtigt.“ Liest die drei § 7.3-Fragen dieses Blatts (vorher leere Bedingung auf M8203-19).
[EN] § 7.3 goals: "Existing-asset data are complete, current and digitally available for the upcoming planning tasks (e.g. georeferenced, vectorised, reference system)." · "The basis for this is an unambiguous plant identification system (AKZ)." · "The legal requirements on critical infrastructure were clarified beforehand and are taken into account in the project." Reads the three § 7.3 questions of this sheet (was an empty condition on M8203-19).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-20' AND x.code = 'REQ-27';
UPDATE compliance_requirements x SET description = 'Rights on digital data clarified.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-20' AND x.code = 'REQ-28';
UPDATE fields x SET description = 'Interfaces between digital BIM communication and Planungs-/Baubesprechungen clarified.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-21' AND x.symbol = 'bim_communication_interfaces';
UPDATE fields x SET description = 'CDE-BIM platform is set up and used as the communication platform.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-21' AND x.symbol = 'cde_used_for_communication';
UPDATE fields x SET description = 'Communication concept is not rigid but adapts to project progress and phases.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-21' AND x.symbol = 'communication_concept_adaptive';
UPDATE fields x SET description = 'Affected parties get access to important info via suitable digital media (e.g. project website).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-21' AND x.symbol = 'public_info_via_digital_media';
UPDATE compliance_requirements x SET description = '§ 7.5.2 (PDF S. 23): „Unter Projektkommunikation wird der Einsatz von Kommunikationsplattformen verstanden. Beim Einsatz der BIM-Planung stehen dafür Werkzeuge bereit und werden eingesetzt.“ Ziele: „Schnittstellen zwischen der rein digitalen Kommunikation (bspw. über das BIM-Modell) und der Kommunikation in Planungs- und Baubesprechungen sind geklärt.“ · „Eine CDE-BIM-Plattform als Kommunikationsplattform ist eingerichtet und wird genutzt.“ — nur bei digitaler Planung nach der BIM-Methodik (Frage auf M8203-19). Vorher leere Bedingung auf M8203-19.
[EN] § 7.5.2: "Project communication means the use of communication platforms. Where BIM planning is used, tools are available for this and are used." Goals: "Interfaces between purely digital communication (e.g. via the BIM model) and communication in planning and site meetings are clarified." · "A CDE-BIM platform is set up and used as the communication platform." — only with digital planning using the BIM method (question on M8203-19). Was an empty condition on M8203-19.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-21' AND x.code = 'REQ-29';
UPDATE compliance_requirements x SET description = '§ 7.5.3 Ziele (PDF S. 23–24): „Betroffene erhalten über geeignete digitale Medien (bspw. Projektwebsite) Zugang zu den für sie wichtigen Informationen.“ · „Ein Kommunikationskonzept ist erarbeitet, welches nicht starr ist, sondern sich dem Projektverlauf anpasst und an den Projektphasen des Projekts orientiert.“ Vorher las das Gate das Feld von REQ-26 (Digital Twin, § 7.2.3) auf M8203-19.
[EN] § 7.5.3 goals: "Affected parties get access to the information important to them through suitable digital media (e.g. a project website)." · "A communication concept is drawn up that is not rigid but adapts to the course of the project and is oriented to its phases." Before, the gate read REQ-26''s field (digital twin, § 7.2.3) on M8203-19.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-21' AND x.code = 'REQ-30';
UPDATE fields x SET description = 'Aggregated fulfilment rate across all Gesamtsystem QE checklists.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-22' AND x.symbol = 'gesamt_anhang_a_fulfilment_pct';
UPDATE fields x SET description = 'Aggregate count of all QE items across Anhang A.1-A.4 (15+8+12+3=38).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-22' AND x.symbol = 'gesamt_anhang_a_items_total';
UPDATE fields x SET description = 'Overall verdict for the Gesamtsystem QE stream.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-22' AND x.symbol = 'gesamt_anhang_a_verdict';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-22-D1 (qe52_items_total + qe53_items_total + qe54_items_total + qe55_items_total — die vererbten Katalogsummen; gedruckt 15 + 8 + 12 + 3 = 38); das manuelle gesamt_anhang_a_items_total bleibt Eingabe (Ablösung STAGED m820_3-D-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-22' AND x.symbol = 'gesamt_anhang_a_items_total_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-22-D2 (qe52_items_rated + qe53_items_rated + qe54_items_rated + qe55_items_rated); unentscheidbar, bis die vier Register-Ausgaben auf M8203-22 vererbt sind (m820_3-C-5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-22' AND x.symbol = 'gesamt_anhang_a_items_rated';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-22-D3 (OR über die 13 pz_52_* / pz_53_* / pz_54_*-Status IN {nicht_erreicht, teilweise_erreicht} — L307 „nicht oder nur unvollständig erreicht“ —, alle auf M8203-22 vererbt); REQ-31 (leere Bedingung) darauf STAGED (m820_3-G-4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-22' AND x.symbol = 'projektstopp_code_a';
UPDATE equations x SET description = 'Plan 3: Σ der vererbten Katalogsummen qe52/53/54/55_items_total (gedruckt 15 + 8 + 12 + 3 = 38 — die Seed-Tabellen QE_A1 … QE_A4); das manuelle gesamt_anhang_a_items_total (VR ==38) bleibt, Ablösung STAGED (m820_3-D-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-22' AND x.equation_number = 'M8203-22-D1';
UPDATE equations x SET description = 'Plan 3: Σ der bewerteten Kriterien über die vier Anhang-A-Register (qe52/53/54/55_items_rated); unentscheidbar, bis die vier Ausgaben auf M8203-22 vererbt sind (m820_3-C-5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-22' AND x.equation_number = 'M8203-22-D2';
UPDATE equations x SET description = 'Plan 3: 1, wenn eines der 13 Phasenziele §5.2 / §5.3 / §5.4 (alle auf M8203-22 vererbt) den Status nicht_erreicht („nicht … erreicht“) oder teilweise_erreicht („nur unvollständig erreicht“, L307) hat, sonst 0 (m820_3-J-2 trägt die engere Nur-nicht-Lesart als Alternative); REQ-31 (M8203-22, leere Bedingung) darauf STAGED (m820_3-G-4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-22' AND x.equation_number = 'M8203-22-D3';
UPDATE fields x SET description = 'Aggregated fulfilment rate across all Projekt QE checklists.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-23' AND x.symbol = 'gesamt_anhang_b_fulfilment_pct';
UPDATE fields x SET description = 'Aggregate count of all QE items across Anhang B.1-B.6 (15+40+50+34+10+6=155).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-23' AND x.symbol = 'gesamt_anhang_b_items_total';
UPDATE fields x SET description = 'Overall verdict for the Projekt QE stream.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-23' AND x.symbol = 'gesamt_anhang_b_verdict';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-23-D1 (qe62_items_total + qe63a_items_total + qe63b_items_total + qe64a_items_total + qe64b_items_total + qe65_items_total + qe66_items_total + qe67_items_total — die vererbten Katalogsummen; gedruckt 15 + 40 + 50 + 34 + 10 + 6 = 155); das manuelle gesamt_anhang_b_items_total bleibt Eingabe (Ablösung STAGED m820_3-D-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-23' AND x.symbol = 'gesamt_anhang_b_items_total_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-23-D2 (qe62_items_rated + qe63a_items_rated + qe63b_items_rated + qe64a_items_rated + qe64b_items_rated + qe65_items_rated + qe66_items_rated + qe67_items_rated); unentscheidbar, bis die acht Register-Ausgaben auf M8203-23 vererbt sind (m820_3-C-5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-23' AND x.symbol = 'gesamt_anhang_b_items_rated';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-23-D3 (OR über die 54 pz_62_* … pz_67_*-Status IN {nicht_erreicht, teilweise_erreicht} — L307 —, alle auf M8203-23 vererbt); REQ-31 darauf STAGED (m820_3-G-4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-23' AND x.symbol = 'projektstopp_code_b';
UPDATE equations x SET description = 'Plan 3: Σ der vererbten Katalogsummen qe62/63a/63b/64a/64b/65/66/67_items_total (gedruckt 15 + 40 + 50 + 34 + 10 + 6 = 155 — die Seed-Tabellen QE_B1 … QE_B6); das manuelle gesamt_anhang_b_items_total (VR ==155) bleibt, Ablösung STAGED (m820_3-D-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-23' AND x.equation_number = 'M8203-23-D1';
