UPDATE equations x SET description = 'Plan 3: 1, wenn eines der 54 Phasenziele §6.2 … §6.7 (alle auf M8203-23 vererbt) den Status nicht_erreicht oder teilweise_erreicht („nicht oder nur unvollständig erreicht“, L307) hat, sonst 0 (m820_3-J-2); REQ-31 darauf STAGED (m820_3-G-4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-23' AND x.equation_number = 'M8203-23-D3';
UPDATE compliance_requirements x SET description = 'All 40 QE items of Anhang B.2 assessed across the two split worksheets (M8203-12 covers Nr.1-21 / M8203-13 covers Nr.22-40).
[Follow-up 1, 2026-10-06] Blatt / sheet M8203-23 „Zusammenfassung QE Projekte“ (vorher / was M8203-11 = QE 6.2, Anhang B.1). Die Prüfung liest die Summen von M8203-12 / -13 (Anhang B.2, § 6.3: „Qualitätselemente (Auswahl) siehe Anhang B. 2 „QE 6.3: Planung““, PDF S. 17; B.2 druckt Nr. 1–40, PDF S. 27–30); diese erreichen nur M8203-23 / -24 — auf M8203-11 wartete die Prüfung dauerhaft. [EN] The check reads the totals of M8203-12 / -13 (Annex B.2, printed Nr. 1–40), which reach M8203-23 / -24 only; on M8203-11 it waited for good.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-23' AND x.code = 'REQ-20';
UPDATE compliance_requirements x SET description = 'All 50 QE items of Anhang B.3 assessed across the two split worksheets (M8203-14 covers Nr.1-17 / M8203-15 covers Nr.18-50).
[Follow-up 1, 2026-10-06] Blatt / sheet M8203-23 „Zusammenfassung QE Projekte“ (vorher / was M8203-11 = QE 6.2, Anhang B.1). Die Prüfung liest die Summen von M8203-14 / -15 (Anhang B.3, § 6.4: „Qualitätselemente (Auswahl) siehe Anhang B. 3 „QE 6.4: Ausführungsvorbereitung““, PDF S. 18; B.3 druckt Nr. 1–50, PDF S. 30–34); diese erreichen nur M8203-23 / -24 — auf M8203-11 wartete die Prüfung dauerhaft. [EN] The check reads the totals of M8203-14 / -15 (Annex B.3, printed Nr. 1–50), which reach M8203-23 / -24 only; on M8203-11 it waited for good.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-23' AND x.code = 'REQ-21';
UPDATE fields x SET description = 'At project closure the workflow checks whether the overall-system concept is fully implemented; if not, the next project is initiated.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-24' AND x.symbol = 'bild1_loop_back_to_konzept_check';
