UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M8203-24-D1 (OR über alle 67 pz_*_status IN {nicht_erreicht, teilweise_erreicht} — L307 —, alle auf M8203-24 vererbt; jedes Phasenziel muss gesetzt sein — nicht zutreffende Phasen als nicht_zutreffend); die Booleans projektstopp_review_triggered (M8203-02) / projektstopp_required bleiben Eingaben, REQ-31 darauf STAGED (m820_3-G-4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-24' AND x.symbol = 'projektstopp_code';
UPDATE fields x SET description = 'If Phasenziele are not or only incompletely achieved, a Projektstopp review is required and risk assessment must determine if/how to continue.
[Flow 1, 2026-10-06] Blatt / sheet M8203-24 „Gesamtverifizierung Qualität“, Abschnitt F (vorher / was M8203-02 „Anwendungsbereich und Grundsätze“): der Auslöser projektstopp_code wird auf M8203-24 berechnet, REQ-31 liest beide dort. § 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich.“ [EN] The trigger is computed on M8203-24 and REQ-31 reads both there.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-24' AND x.symbol = 'projektstopp_review_triggered';
UPDATE equations x SET description = 'Plan 3: 1, wenn irgendeines der 67 Phasenziele (Anhang A oder B, alle auf M8203-24 vererbt) den Status nicht_erreicht oder teilweise_erreicht („nicht oder nur unvollständig erreicht“, L307) hat, sonst 0; jedes Phasenziel muss gesetzt sein (nicht zutreffende Phasen: nicht_zutreffend) — sonst manual_required; die Booleans projektstopp_review_triggered / projektstopp_required bleiben Eingaben (m820_3-G-4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-24' AND x.equation_number = 'M8203-24-D1';
UPDATE compliance_requirements x SET description = '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Gesamtsicht auf M8203-24: ist der berechnete Projektstopp-Code 1 (mindestens ein Phasenziel „Nicht erreicht“ oder „Teilweise erreicht“; „Phase noch nicht erreicht“ zählt nicht), muss „Projektstopp-Prüfung ausgelöst“ (M8203-02) bejaht sein. Die blockierenden Prüfungen je Phase sind REQ-06-2 … REQ-14-2. Vorher leere Bedingung auf M8203-22.
[EN] § 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Overall view on M8203-24: when the computed Projektstopp code is 1 (at least one phase goal "not met" or "partially met"; "phase not reached yet" does not count), "Projektstopp review triggered" (M8203-02) must be Yes. The blocking per-phase checks are REQ-06-2 … REQ-14-2. Was an empty condition on M8203-22.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-24' AND x.code = 'REQ-31';
UPDATE compliance_requirements x SET description = 'Final sign-off: Gesamtsystem + Projekt verdicts aggregated and signed off by Ingenieur and Auftraggeber.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-24' AND x.code = 'REQ-32';
COMMIT;
